static cairo_surface_t *
raster_source_pattern_acquire (cairo_pattern_t *pattern,
                               void *callback_data,
                               cairo_surface_t *target,
                               const cairo_rectangle_int_t *extents)
{
  PycairoRasterSource *priv = cairo_pattern_get_user_data (
      pattern, &PycairoRasterSourcePattern_key);
  PyObject *result;
  PyObject *py_pattern;
  PyObject *py_target;
  PyObject *py_extents;
  cairo_surface_t *surface;

  if (priv == NULL) {
    PyErr_SetString (PyExc_RuntimeError,
                     "no private raster source data available");
    return NULL;
  }

  if (priv->acquire.callback == NULL) {
    PyErr_SetString (PyExc_RuntimeError, "no acquire callback");
    return NULL;
  }

  py_pattern = PycairoPattern_FromPattern (cairo_pattern_reference (pattern), NULL);
  if (py_pattern == NULL)
    return NULL;

  py_target = PycairoSurface_FromSurface (cairo_surface_reference (target), NULL);
  if (py_target == NULL) {
    Py_DECREF (py_pattern);
    return NULL;
  }

  py_extents = PycairoRectangleInt_FromRectangleInt (extents);
  if (py_extents == NULL) {
    Py_DECREF (py_pattern);
    Py_DECREF (py_target);
    return NULL;
  }

  result = PyObject_CallFunctionObjArgs (priv->acquire.callback,
                                         priv->acquire.callback_data,
                                         py_pattern, py_target, py_extents,
                                         NULL);
  Py_DECREF (py_pattern);
  Py_DECREF (py_target);
  Py_DECREF (py_extents);

  if (result == NULL)
    return NULL;

  if (!PycairoSurface_Check (result)) {
    PyErr_SetString (PyExc_TypeError,
                     "acquire callback didn't return a cairo.Surface");
    Py_DECREF (result);
    return NULL;
  }

  surface = ((PycairoSurface *)result)->surface;
  cairo_surface_reference (surface);
  Py_DECREF (result);
  return surface;
}
